def test_field_roundtrip(regs):
    regs.RSTART_REG.START.write(0x1)
    assert regs.RSTART_REG.START.read() == 0x1
    regs.RSTART_REG.START.write(0)
    regs.RADDR_REG.ADDR.write(0xdeadbeef)
    assert regs.RADDR_REG.ADDR.read() == 0xdeadbeef
    regs.RADDR_REG.ADDR.write(0)
    regs.RLENGTH_REG.LENGTH.write(0xdeadbeef)
    assert regs.RLENGTH_REG.LENGTH.read() == 0xdeadbeef
    regs.RLENGTH_REG.LENGTH.write(0)
    regs.WSTART_REG.START.write(0x1)
    assert regs.WSTART_REG.START.read() == 0x1
    regs.WSTART_REG.START.write(0)
    regs.WADDR_REG.ADDR.write(0xdeadbeef)
    assert regs.WADDR_REG.ADDR.read() == 0xdeadbeef
    regs.WADDR_REG.ADDR.write(0)
    regs.WNBURST_REG.NBURST.write(0xdeadbeef)
    assert regs.WNBURST_REG.NBURST.read() == 0xdeadbeef
    regs.WNBURST_REG.NBURST.write(0)


def test_register_independence(regs):
    regs.RSTART_REG.START.write(0x1)
    regs.RADDR_REG.ADDR.write(0xabcd)
    regs.RLENGTH_REG.LENGTH.write(0xabcd)
    regs.WSTART_REG.START.write(0x1)
    regs.WADDR_REG.ADDR.write(0xabcd)
    regs.WNBURST_REG.NBURST.write(0xabcd)
    assert regs.RSTART_REG.START.read() == 0x1
    assert regs.RADDR_REG.ADDR.read() == 0xabcd
    assert regs.RLENGTH_REG.LENGTH.read() == 0xabcd
    assert regs.WSTART_REG.START.read() == 0x1
    assert regs.WADDR_REG.ADDR.read() == 0xabcd
    assert regs.WNBURST_REG.NBURST.read() == 0xabcd
